      SUBROUTINE TWIT1ECC     DETERMINES CONTRIBUTION OF FIRST-ORDER TRANSFER MATRIX TOC     TRANSFORM OF PARTIALS OF ETA FUNCTIONC      C ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETATC.CIN'      INCLUDE 'R.CIN'C      DO 10 J = 1, 6      SS = 0.0      DO 5 K = 1, 6      SS = SS + R(J,K)*ETAV(K,NV2)    5 CONTINUE      ETAT(J) = SS   10 CONTINUEC      RETURN      END